import { SendEmail } from "./types";

// A mock mailer standing in for a real SMTP client (e.g. nodemailer). No
// network calls happen here -- every "send" is recorded in `callLog` so
// tests can assert on exactly who was emailed and with what content.
export interface CallLogEntry {
  to: string;
  subject: string;
  body: string;
}

export interface MockMailer {
  sendEmail: SendEmail;
  callLog: CallLogEntry[];
  // Arms the mailer to reject the *next* sendEmail call (only) with a
  // simulated SMTP failure, then return to normal behavior. Useful for
  // testing that a single failed send doesn't take down the whole batch.
  failNextSend: () => void;
}

export function createMockMailer(): MockMailer {
  const callLog: CallLogEntry[] = [];
  let shouldFailNext = false;

  const sendEmail: SendEmail = async (to, subject, body) => {
    if (shouldFailNext) {
      shouldFailNext = false;
      throw new Error(`Simulated SMTP failure sending to ${to}`);
    }
    callLog.push({ to, subject, body });
  };

  return {
    sendEmail,
    callLog,
    failNextSend: () => {
      shouldFailNext = true;
    },
  };
}
